INSERT INTO `change_operations` VALUES ('cmukzkhd200n6myrwsi0p72yx','cmukzkhc400n0myrwoc9zzr7h','cmukzkhcd00n2myrwhqag2ctx','ADD_PROVISION','Pasal I angka 1 UU No. 19 Tahun 2016',NULL,'Setiap Penyelenggara Sistem Elektronik wajib menghapus Informasi Elektronik dan/atau Dokumen Elektronik yang tidak relevan yang berada di bawah kendalinya atas permintaan Orang yang bersangkutan berdasarkan penetapan pengadilan.','{\"id\":\"op-2016-pasal-26-add-3\",\"orderInSet\":1,\"operationType\":\"ADD_PROVISION\",\"sourceReference\":\"Pasal I angka 1 UU No. 19 Tahun 2016\",\"targetCanonicalPath\":\"uu-11-2008/pasal-26/ayat-3\",\"parentCanonicalPath\":\"uu-11-2008/pasal-26\",\"newNode\":{\"canonicalPath\":\"uu-11-2008/pasal-26/ayat-3\",\"type\":\"AYAT\",\"orderIndex\":3,\"label\":\"Ayat (3)\",\"content\":\"Setiap Penyelenggara Sistem Elektronik wajib menghapus Informasi Elektronik dan/atau Dokumen Elektronik yang tidak relevan yang berada di bawah kendalinya atas permintaan Orang yang bersangkutan berdasarkan penetapan pengadilan.\",\"versionTag\":\"AMENDMENT_2016\",\"children\":[]}}',1),('cmukzkhdc00n8myrwmlin8cr4','cmukzkhc400n0myrwoc9zzr7h','cmukzkge400c6myrwgk18onv3','REPLACE_PROVISION','Pasal I angka 2 UU No. 19 Tahun 2016','Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan penghinaan dan/atau pencemaran nama baik.','Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan penghinaan dan/atau pencemaran nama baik.','{\"id\":\"op-2016-pasal-27-penjelasan\",\"orderInSet\":2,\"operationType\":\"REPLACE_PROVISION\",\"sourceReference\":\"Pasal I angka 2 UU No. 19 Tahun 2016\",\"targetCanonicalPath\":\"uu-11-2008/pasal-27/ayat-3\",\"previousContent\":\"Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan penghinaan dan/atau pencemaran nama baik.\",\"newContent\":\"Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan penghinaan dan/atau pencemaran nama baik.\",\"newExplanation\":\"Ketentuan pada ayat ini mengacu pada ketentuan penghinaan dan/atau pencemaran nama baik sebagaimana diatur dalam KUHP.\"}',2),('cmukzkhdm00namyrwc7rrfc3a','cmukzkhc400n0myrwoc9zzr7h','cmukzkh2900jumyrwlx5iwahe','REPLACE_PROVISION','Pasal I angka 6 UU No. 19 Tahun 2016','Setiap Orang yang memenuhi unsur sebagaimana dimaksud dalam Pasal 27 ayat (1), ayat (2), ayat (3), atau ayat (4) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah).','Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan muatan kesusilaan dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah). Sedangkan ancaman pidana Pasal 27 ayat (3) dipotong menjadi pidana penjara paling lama 4 (empat) tahun dan/atau denda paling banyak Rp750.000.000,00 (tujuh ratus lima puluh juta rupiah).','{\"id\":\"op-2016-pasal-45-replace\",\"orderInSet\":3,\"operationType\":\"REPLACE_PROVISION\",\"sourceReference\":\"Pasal I angka 6 UU No. 19 Tahun 2016\",\"targetCanonicalPath\":\"uu-11-2008/pasal-45/ayat-1\",\"previousContent\":\"Setiap Orang yang memenuhi unsur sebagaimana dimaksud dalam Pasal 27 ayat (1), ayat (2), ayat (3), atau ayat (4) dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah).\",\"newContent\":\"Setiap Orang yang dengan sengaja dan tanpa hak mendistribusikan muatan kesusilaan dipidana dengan pidana penjara paling lama 6 (enam) tahun dan/atau denda paling banyak Rp1.000.000.000,00 (satu miliar rupiah). Sedangkan ancaman pidana Pasal 27 ayat (3) dipotong menjadi pidana penjara paling lama 4 (empat) tahun dan/atau denda paling banyak Rp750.000.000,00 (tujuh ratus lima puluh juta rupiah).\"}',3),('cmukzkhe200nemyrw39fjtcwc','cmukzkhdv00ncmyrw9mv57vmm','cmukzkge400c6myrwgk18onv3','REPEAL_PROVISION','Pasal I angka 2 UU No. 1 Tahun 2024','Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan penghinaan dan/atau pencemaran nama baik.',NULL,'{\"id\":\"op-2024-pasal-27-repeal-3\",\"orderInSet\":1,\"operationType\":\"REPEAL_PROVISION\",\"sourceReference\":\"Pasal I angka 2 UU No. 1 Tahun 2024\",\"targetCanonicalPath\":\"uu-11-2008/pasal-27/ayat-3\",\"repealNote\":\"Ketentuan ayat (3) Pasal 27 dihapus.\"}',1),('cmukzkhf700nkmyrwog2ozfuj','cmukzkhdv00ncmyrw9mv57vmm','cmukzkheo00ngmyrw9g5b90w5','ADD_PROVISION','Pasal I angka 3 UU No. 1 Tahun 2024',NULL,'Setiap Orang dengan sengaja menyerang kehormatan atau nama baik orang lain dengan menuduhkan suatu hal melalui Informasi Elektronik dan/atau Dokumen Elektronik dengan maksud agar hal tersebut diketahui umum.','{\"id\":\"op-2024-pasal-27a-add\",\"orderInSet\":2,\"operationType\":\"ADD_PROVISION\",\"sourceReference\":\"Pasal I angka 3 UU No. 1 Tahun 2024\",\"targetCanonicalPath\":\"uu-11-2008/pasal-27a\",\"parentCanonicalPath\":\"uu-11-2008/bab-vii\",\"newNode\":{\"canonicalPath\":\"uu-11-2008/pasal-27a\",\"type\":\"PASAL\",\"orderIndex\":27.1,\"label\":\"Pasal 27A\",\"title\":\"Penyerangan Kehormatan atau Nama Baik\",\"content\":\"Setiap Orang dengan sengaja menyerang kehormatan atau nama baik orang lain dengan menuduhkan suatu hal melalui Informasi Elektronik dan/atau Dokumen Elektronik dengan maksud agar hal tersebut diketahui umum.\",\"versionTag\":\"AMENDMENT_2024\",\"children\":[]}}',2),('cmukzkhfx00nqmyrwcjuwx1ie','cmukzkhdv00ncmyrw9mv57vmm','cmukzkhfe00nmmyrwfmd3ysme','ADD_PROVISION','Pasal I angka 3 UU No. 1 Tahun 2024',NULL,'Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan Informasi Elektronik dan/atau Dokumen Elektronik dengan maksud untuk menguntungkan diri sendiri atau orang lain secara melawan hukum, memaksa orang dengan ancaman pencemaran atau kekerasan.','{\"id\":\"op-2024-pasal-27b-add\",\"orderInSet\":3,\"operationType\":\"ADD_PROVISION\",\"sourceReference\":\"Pasal I angka 3 UU No. 1 Tahun 2024\",\"targetCanonicalPath\":\"uu-11-2008/pasal-27b\",\"parentCanonicalPath\":\"uu-11-2008/bab-vii\",\"newNode\":{\"canonicalPath\":\"uu-11-2008/pasal-27b\",\"type\":\"PASAL\",\"orderIndex\":27.2,\"label\":\"Pasal 27B\",\"title\":\"Ancaman Pencemaran & Pemerasan Khusus\",\"content\":\"Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan Informasi Elektronik dan/atau Dokumen Elektronik dengan maksud untuk menguntungkan diri sendiri atau orang lain secara melawan hukum, memaksa orang dengan ancaman pencemaran atau kekerasan.\",\"versionTag\":\"AMENDMENT_2024\",\"children\":[]}}',3);
/*!40000 ALTER TABLE `change_operations` ENABLE KEYS */;
UNLOCK TABLES;

