INSERT INTO `legal_instruments` VALUES ('cmukzkf9b0000myrwdhrzn3n0','ite','UU',11,2008,'Informasi dan Transaksi Elektronik','UU ITE','Mengatur transaksi elektronik, tanda tangan digital, perbuatan yang dilarang, fitnah online, dan alat bukti elektronik. Diubah dua kali (2016, 2024) dan menjadi pilot konsolidasi deterministik.','DIUBAH','2008-04-21 00:00:00.000','2008-04-21 00:00:00.000','2008-04-21 00:00:00.000',NULL,58,4843,'2026-09-28 08:29:03.166','2026-09-28 08:29:06.003',NULL,NULL,'','{\"menimbang\":[\"bahwa globalisasi informasi telah menempatkan Indonesia sebagai bagian dari masyarakat informasi dunia sehingga mengharuskan dibentuknya pengaturan mengenai pengelolaan Informasi dan Transaksi Elektronik di tingkat nasional sehingga pembangunan Teknologi Informasi dapat dilakukan secara optimal, merata, dan menyebar ke seluruh lapisan masyarakat guna mencerdaskan kehidupan bangsa;\",\"bahwa perkembangan dan kemajuan Teknologi Informasi yang demikian pesat telah menyebabkan perubahan kegiatan kehidupan manusia dalam berbagai bidang yang secara langsung telah memengaruhi lahirnya bentuk-bentuk perbuatan hukum baru;\",\"bahwa penggunaan dan pemanfaatan Teknologi Informasi harus terus dikembangkan untuk menjaga, memelihara, dan memperkukuh persatuan dan kesatuan nasional berdasarkan Peraturan Perundang-undangan demi kepentingan nasional;\",\"bahwa pemanfaatan Teknologi Informasi berperan penting dalam perdagangan dan pertumbuhan perekonomian nasional untuk mewujudkan kesejahteraan masyarakat;\",\"bahwa pemerintah perlu mendukung pengembangan Teknologi Informasi melalui infrastruktur hukum dan pengaturannya sehingga pemanfaatan Teknologi Informasi dilakukan secara aman untuk mencegah penyalahgunaannya dengan memperhatikan nilai-nilai agama dan sosial budaya masyarakat Indonesia;\",\"bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a, huruf b, huruf c, huruf d, huruf e, dan huruf f, perlu membentuk Undang-Undang tentang Informasi dan Transaksi Elektronik; Mengingat :. . . PRESIDEN REPUBLIK INDONESIA - 2 -\"],\"mengingat\":[]}'),('cmukzkhbp00mxmyrw6cx4pzt5','uu-19-2016','UU',19,2016,'Perubahan Atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik','UU ITE (Amandemen 1)',NULL,'BERLAKU','2016-11-28 00:00:00.000','2016-11-28 00:00:00.000','2016-11-28 00:00:00.000',NULL,251,5952,'2026-09-28 08:29:05.845','2026-09-28 08:29:05.845',NULL,NULL,NULL,NULL),('cmukzkhbw00mymyrwccx3hj76','uu-1-2024','UU',1,2024,'Perubahan Kedua Atas Undang-Undang Nomor 11 Tahun 2008 tentang Informasi dan Transaksi Elektronik','UU ITE (Amandemen 2)',NULL,'BERLAKU','2024-01-02 00:00:00.000','2024-01-02 00:00:00.000','2024-01-02 00:00:00.000',NULL,8,6916,'2026-09-28 08:29:05.852','2026-09-28 08:29:05.852',NULL,NULL,NULL,NULL),('cmun60idq0000my4ov3e1818j','uu-1-1974','UU',1,1974,'Undang-Undang Nomor 1 Tahun 1974','UU No. 1 Tahun 1974',NULL,'BERLAKU','1974-01-01 00:00:00.000','1974-01-01 00:00:00.000','1974-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:03.758','2026-09-29 21:05:03.758',85,'QUARANTINE',NULL,'null'),('cmun60k4b00izmy4oh5129w86','uu-1-2023','UU',1,2023,'UU No. 1 Tahun 2023 tentang Kitab Undang-Undang Hukum Pidana','UU No. 1 Tahun 2023','Untuk mewujudkan hukum pidana nasional Negara Kesatuan Republik Indonesia yang berdasarkan Pancasila dan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 serta asas hukum umum yang diakui masyarakat bangsa-bangsa, perlu disusun hukum pidana nasional untuk mengganti Kitab Undang-Undang Hukum Pidana warisan pemerintah kolonial Hindia Belanda.','BERLAKU','2023-01-01 00:00:00.000','2023-01-01 00:00:00.000','2023-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:06.012','2026-09-29 21:05:06.012',85,'QUARANTINE',NULL,'null'),('cmun60ueq04egmy4odwm0rezt','uu-27-2022','UU',27,2022,'UU No. 27 Tahun 2022 tentang Pelindungan Data Pribadi','UU No. 27 Tahun 2022','Pelindungan data pribadi merupakan salah satu hak asasi manusia yang merupakan bagian dari pelindungan diri pribadi maka perlu diberikan landasan hukum untuk memberikan keamanan atas data pribadi, berdasarkan Undang-Undang Dasar Negara Republik Indonesia Tahun 1945. Pengaturan data pribadi saat ini terdapat di dalam beberapa peraturan perundang-undangan maka untuk meningkatkan efektivitas dalam pelaksanaan pelindungan data pribadi diperlukan pengaturan mengenai pelindungan data pribadi dalam suatu undang-undang.','BERLAKU','2022-01-01 00:00:00.000','2022-01-01 00:00:00.000','2022-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:19.346','2026-09-29 21:05:19.346',85,'QUARANTINE',NULL,'null'),('cmun60x7k058dmy4outl86qhw','uu-40-2007','UU',40,2007,'UU No. 40 Tahun 2007 tentang Perseroan Terbatas','UU No. 40 Tahun 2007','bahwa perekonomian nasional yang diselenggarakan berdasar atas demokrasi ekonomi dengan prinsip kebersamaan, efisiensi berkeadilan, berkelanjutan, berwawasan lingkungan, kemandirian, serta dengan menjaga keseimbangan kemajuan dan kesatuan ekonomi nasional, perlu didukung oleh kelembagaan perekonomian yang kokoh dalam rangka mewujudkan kesejahteraan masyarakat;&#xD;&#xA;bahwa dalam rangka lebih meningkatkan pembangunan perekonomian nasional dan sekaligus memberikan landasan yang kokoh bagi dunia usaha dalam menghadapi perkembangan perekonomian dunia dan kemajuan ilmu pengetahuan dan teknologi di era globalisasi pada masa mendatang, perlu didukung oleh suatu undang-undang yang mengatur tentang perseroan terbatas yang dapat menjamin terselenggaranya iklim dunia usaha yang kondusif;&#xD;&#xA;bahwa perseroan terbatas sebagai salah satu pilar pembangunan perekonomian nasional perlu diberikan landasan hukum untuk lebih memacu pembangunan nasional yang disusun sebagai usaha bersama berdasar atas asas kekeluargaan;&#xD;&#xA;bahwa Undang-Undang Nomor 1 Tahun 1995 tentang Perseroan Terbatas dipandang sudah tidak sesuai lagi dengan perkembangan hukum dan kebutuhan masyarakat sehingga perlu diganti dengan undang-undang yang baru.','BERLAKU','2007-01-01 00:00:00.000','2007-01-01 00:00:00.000','2007-01-01 00:00:00.000',NULL,106,4756,'2026-09-29 21:05:22.976','2026-09-29 21:05:22.976',100,'AUTO_PUBLISH',NULL,'null'),('cmun6149407u6my4oukt7gmzu','uu-8-1999','UU',8,1999,'Undang-Undang Nomor 8 Tahun 1999','UU No. 8 Tahun 1999',NULL,'BERLAKU','1999-01-01 00:00:00.000','1999-01-01 00:00:00.000','1999-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:32.104','2026-09-29 21:05:32.104',100,'AUTO_PUBLISH',NULL,'null'),('cmun6165u08kjmy4ouel1akvq','uu-no-1-tahun-2025','UU',1,2025,'Undang-Undang Nomor 1 Tahun 2025','UU No. 1 Tahun 2025',NULL,'BERLAKU','2025-01-01 00:00:00.000','2025-01-01 00:00:00.000','2025-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:34.578','2026-09-29 21:05:34.578',85,'QUARANTINE',NULL,'null'),('cmun6193b09ommy4o77jl9yt5','uu-no-1-tahun-2026','UU',1,2026,'Undang-Undang Nomor 1 Tahun 2026','UU No. 1 Tahun 2026',NULL,'BERLAKU','2026-01-01 00:00:00.000','2026-01-01 00:00:00.000','2026-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:38.376','2026-09-29 21:05:38.376',0,'QUARANTINE',NULL,'null'),('cmun6194b09ormy4ooh04n2s1','uu-no-10-tahun-2025','UU',10,2025,'Undang-Undang Nomor 10 Tahun 2025','UU No. 10 Tahun 2025',NULL,'BERLAKU','2025-01-01 00:00:00.000','2025-01-01 00:00:00.000','2025-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:38.411','2026-09-29 21:05:38.411',85,'QUARANTINE',NULL,'null'),('cmun619b109qqmy4offp1xrjm','uu-no-11-tahun-2025','UU',11,2025,'Undang-Undang Nomor 11 Tahun 2025','UU No. 11 Tahun 2025',NULL,'BERLAKU','2025-01-01 00:00:00.000','2025-01-01 00:00:00.000','2025-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:38.654','2026-09-29 21:05:38.654',100,'AUTO_PUBLISH',NULL,'null'),('cmun619hu09sxmy4ottcwgkqw','uu-no-12-tahun-2025','UU',12,2025,'Undang-Undang Nomor 12 Tahun 2025','UU No. 12 Tahun 2025',NULL,'BERLAKU','2025-01-01 00:00:00.000','2025-01-01 00:00:00.000','2025-01-01 00:00:00.000',NULL,NULL,NULL,'2026-09-29 21:05:38.898','2026-09-29 21:05:38.898',100,'AUTO_PUBLISH',NULL,'n