DROP TABLE IF EXISTS `provision_revisions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `provision_revisions` (
  `id` varchar(191) NOT NULL,
  `provisionId` varchar(191) NOT NULL,
  `versionTag` varchar(191) NOT NULL,
  `content` text NOT NULL,
  `explanation` text DEFAULT NULL,
  `effectiveFrom` datetime(3) NOT NULL,
  `effectiveUntil` datetime(3) DEFAULT NULL,
  `changeSetId` varchar(191) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  KEY `provision_revisions_provisionId_fkey` (`provisionId`),
  KEY `provision_revisions_changeSetId_fkey` (`changeSetId`),
  CONSTRAINT `provision_revisions_changeSetId_fkey` FOREIGN KEY (`changeSetId`) REFERENCES `change_sets` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `provision_revisions_provisionId_fkey` FOREIGN KEY (`provisionId`) REFERENCES `provisions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
