DROP TABLE IF EXISTS `provisions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `provisions` (
  `id` varchar(191) NOT NULL,
  `legalInstrumentId` varchar(191) NOT NULL,
  `parentId` varchar(191) DEFAULT NULL,
  `type` enum('BUKU','LAMPIRAN','BAB','BAGIAN','PARAGRAF','PASAL','AYAT','HURUF','ANGKA','PENJELASAN_UMUM','PENJELASAN_PASAL') NOT NULL,
  `orderIndex` double NOT NULL,
  `label` varchar(191) NOT NULL,
  `title` varchar(191) DEFAULT NULL,
  `canonicalPath` varchar(191) NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `provisions_legalInstrumentId_canonicalPath_key` (`legalInstrumentId`,`canonicalPath`),
  KEY `provisions_canonicalPath_idx` (`canonicalPath`),
  KEY `provisions_parentId_fkey` (`parentId`),
  CONSTRAINT `provisions_legalInstrumentId_fkey` FOREIGN KEY (`legalInstrumentId`) REFERENCES `legal_instruments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `provisions_parentId_fkey` FOREIGN KEY (`parentId`) REFERENCES `provisions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

